#pragma once
static void panel_seq_render(void){ds_pattern *p=ds_pattern_at(ds.pattern);ds_track *t=&p->track[panel.track];int selected=dc(panel.seq_step,0,t->length-1),base=selected/16*16,drum=panel_seq_drum(),n=panel_seq_note();char b[64],*at=pn(ps(b,"STEP "),selected+1);at=ps(at,drum?" PAD":" N");pn(at,n+1);ptext(5,87,b,UC_AMBER,1,22);at=pn(b,base+1);at=ps(at,"-");pn(at,dc(base+16,1,t->length));ptext(191,87,b,UC_MUTED,1,8);
 int rows=drum?11:4,height=drum?7:12,y0=drum?96:112;
 for(int row=0;row<rows;row++){if(drum)ptext(3,y0+row*height,(d_sample_views[row].pcm?d_drum_name(row):row==3?"T8":row==4?"T6":d_drum_name(row)),row==n?UC_AMBER:UC_MUTED,1,3);else{pn(ps(b,"N"),row+1);ptext(4,y0+row*height+2,b,row==n?UC_AMBER:UC_MUTED,1,2);}for(int col=0;col<16;col++){int step=base+col;if(step>=t->length)continue;ds_step *s=&t->step[step];int on=drum?!!(p->hits[step]&(1u<<row)):!(s->note[row]&128),x=24+13*col,y=y0+row*height;pr(x,y,11,height-1,UC_TILE);if(on){uint32_t c=t->mute?UC_MUTED:dub_accents[panel.track];int h=1+s->velocity*(height-3)/127;pr(x+1,y+height-2-h,9,h,c);}if(s->condition!=DS_ALWAYS)pr(x+9,y,2,1,UC_CYAN);}}
 for(int col=0;col<16;col++){int step=base+col;if(step>=t->length)continue;int x=23+13*col;if(step==selected){pr(x,y0-1,13,1,UC_AMBER);pr(x,y0+rows*height-1,13,1,UC_AMBER);pr(x,y0-1,1,rows*height+1,UC_AMBER);pr(x+12,y0-1,1,rows*height+1,UC_AMBER);}if(ds.playing&&ds.started&&ds.play[panel.track]==(uint32_t)step)pr(x+2,y0+rows*height+1,9,2,UC_CYAN);}
 if(!drum){int x=24;ds_step *s=&t->step[selected];for(int k=0;k<4;k++){dub_control c=pc(-20,0,0,"",s->note[k]&127,0,127);char note[24];pvalue(c,note);ptext(x,98,note,s->note[k]&128?UC_MUTED:UC_TEXT,1,4);x+=51;}}
 if(ds.saving>=0){pn(ps(b,"SAVING BANK "),ds.saving+1);ptext(5,180,b,UC_CYAN,1,36);}else if(ds.error)ptext(5,180,"SAVE FAILED / STOP THEN RETRY SAVE",UC_AMBER,1,38);else ptext(5,180,panel.page[9]==0?"ALGO/OCT STEP  SHIFT OCT NOTE/PAD":panel.page[9]==1?"TRACK LENGTH / GRID / TYPE / MUTE":panel.page[9]==2?"NEXT AT LONGEST TRACK / SAVE STOPPED":"FILL + TRIG ARE HELD PERFORMANCE KEYS",UC_MUTED,1,38);
}
